using System;using System.Linq;using System.Drawing;using System.Threading;using System.Threading.Tasks;class RoutePlanTest{
static void Check(bool ok){if(!ok)throw new Exception("Streckentest fehlgeschlagen");}
[STAThread]static void Main(){var inv=new Inventory();var root=new Device("5690"){Role="master"};var ap=new Device("450E"){IP="192.168.178.25"};var mini=new Device("Mini"){IP="192.168.178.53"};inv.Devices.AddRange(new[]{root,ap,mini});inv.Links.Add(new Link{A=root,B=ap});inv.Links.Add(new Link{A=ap,B=mini});var plan=RoutePlan.Build(inv,mini);Check(plan.Hops.Count==3&&plan.Hops[1].Host==ap.IP);int calls=0;Atlas.RunRoute(plan.Hops,h=>{calls++;return Task.FromResult(h==ap.IP?new EchoValue{Error="TimedOut"}:new EchoValue{Ms=2});},()=>{},CancellationToken.None,3,25).GetAwaiter().GetResult();Check(calls==9&&plan.Hops.All(h=>h.Points.Count==3));using(var graph=new RoutePlot{Hops=plan.Hops,Size=new Size(620,180)})using(var bmp=new Bitmap(620,180))graph.DrawToBitmap(bmp,graph.ClientRectangle);
var silver=RoutePlan.Build(inv,new Device("Silvercrest"){IP="192.168.178.66"});Check(silver.Hops.Count==4&&silver.Hops[2].Host==null);var c=new CancellationTokenSource();Atlas.RunRoute(silver.Hops,h=>Task.FromResult(new EchoValue{Ms=1}),()=>c.Cancel(),c.Token,1,100).Wait();try{Atlas.RunRoute(plan.Hops,h=>{throw new Exception();},()=>{},c.Token).GetAwaiter().GetResult();throw new Exception("Abbruch");}catch(OperationCanceledException){}Console.WriteLine("OK");}}